            <tr><td className="px-3 py-2 text-xs">10</td><td className="px-3 py-2 text-xs">山梨県</td><td className="px-3 py-2 text-xs">4件</td><td className="px-3 py-2 text-xs">身延町桑の木登木、市川三郷町小学生目撃など</td></tr>
